SELECT DISTINCT p.* FROM permissions p INNER JOIN role_permissions rp ON p.id = rp.permission_id INNER JOIN roles r ON rp.role_id = r.id WHERE r.name IN
#{roleName}
AND p.deleted = false AND r.deleted = false

SELECT p.id, p.code, p.description, p.created_date AS createdDate FROM permissions p WHERE p.deleted = false
AND (p.code ILIKE '%' || #{keyword} || '%' OR p.description ILIKE '%' || #{keyword} || '%')
ORDER BY p.code LIMIT #{limit} OFFSET #{offset}
